import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, test } from "vite-plus/test";
import { groupByLetter, renderGroup, renderIndex, renderNames } from "../scripts/render.ts";
import type { Food } from "../src/food.ts";

const HEADER =
  "// Generated by scripts/generate.ts from data/foods. Do not edit; edit data/foods instead.";

const per100g: Food["per100g"] = {
  fat: "7.09",
  saturates: "1.43",
  monounsaturates: "2.514",
  polyunsaturates: "2.86",
  carbohydrate: "53.7",
  sugars: "1.08",
  starch: "52.6",
  polyols: "0",
  fibre: "9.3",
  protein: "11.375",
  sodium: "0.008",
  alcohol: "0",
  organicAcids: null,
};

const food = (code: string, de = "Hafer ganzes Korn, roh", en = "Oat whole grain, raw"): Food => ({
  code,
  name: { de, en },
  per100g,
  marks: {},
  sources: [{ source: "bls-4.0", id: code, nutrients: ["fat", "saturates"] }],
});

describe("group split by the first letter of the code (BLS documentation 2.4)", () => {
  test("every food lands in its letter, letters and codes in a fixed order", () => {
    const groups = groupByLetter([
      food("M5B1600"),
      food("C131000"),
      food("M100000"),
      food("C110000"),
    ]);
    expect([...groups.keys()]).toEqual(["C", "M"]);
    expect(groups.get("C")?.map((f) => f.code)).toEqual(["C110000", "C131000"]);
    expect(groups.get("M")?.map((f) => f.code)).toEqual(["M100000", "M5B1600"]);
  });

  test("the same foods in any order give the same groups", () => {
    const foods = [food("M5B1600"), food("C131000"), food("M100000")];
    const one = [...groupByLetter(foods)].map(([letter, list]) => renderGroup(letter, list));
    const other = [...groupByLetter([...foods].reverse())].map(([letter, list]) =>
      renderGroup(letter, list),
    );
    expect(other).toEqual(one);
  });
});

describe("a group module", () => {
  test("one typed named export per food, its names as doc comment", () => {
    expect(renderGroup("C", [food("C131000")])).toBe(
      [
        HEADER,
        'import type { Food } from "../food.ts";',
        "",
        "/** Hafer ganzes Korn, roh (Oat whole grain, raw) */",
        `export const C131000: Food = ${JSON.stringify(food("C131000"))};`,
        "",
      ].join("\n"),
    );
  });

  test("a name cannot close the doc comment", () => {
    expect(renderGroup("C", [food("C131000", "a */ b", "c")])).toContain("/** a *\\/ b (c) */");
  });

  test("the module reads back to exactly the foods", async () => {
    const foods = [food("C131000"), food("C110000", 'Grieß "fein"', "Semolina\\fine")];
    const path = join(mkdtempSync(join(tmpdir(), "bls-render-")), "c.ts");
    writeFileSync(path, renderGroup("C", foods));
    const module: Record<string, unknown> = await import(path);
    expect(Object.fromEntries(Object.entries(module))).toEqual({
      C110000: foods[1],
      C131000: foods[0],
    });
  });

  test.each([
    ["a code that is no identifier", "C-131000", "C"],
    ["a code of another group", "M131000", "C"],
  ])("%s is refused", (_, code, letter) => {
    expect(() => renderGroup(letter, [food(code)])).toThrow(new RegExp(code));
  });
});

test("the group index re-exports every group, nothing else", () => {
  expect(renderIndex(["B", "C"])).toBe(
    [HEADER, 'export * from "./b.ts";', 'export * from "./c.ts";', ""].join("\n"),
  );
});

describe("the names of one language", () => {
  test("code and name only, sorted by code", () => {
    const foods = [food("M100000", "Milch", "Milk"), food("C131000")];
    expect(renderNames("en", foods)).toBe(
      [
        HEADER,
        "",
        `export const names: Record<string, string> = ${JSON.stringify({
          C131000: "Oat whole grain, raw",
          M100000: "Milk",
        })};`,
        "",
      ].join("\n"),
    );
  });

  test("the module reads back to exactly the names", async () => {
    const foods = [food("C110000", 'Grieß "fein"', "Semolina\\fine")];
    const path = join(mkdtempSync(join(tmpdir(), "bls-names-")), "de.ts");
    writeFileSync(path, renderNames("de", foods));
    const module: Record<string, unknown> = await import(path);
    expect({ ...module }).toEqual({ names: { C110000: 'Grieß "fein"' } });
  });
});
